1. Create a `TooltipContext` to store the state of the currently opened Tooltip and a function to close it.

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const value = { tooltip, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
  );
};
```

2. Wrap the Tooltip component with the TooltipProvider and pass the tooltip state and closeTooltip function as props.

```jsx
import React from 'react';
import { Tooltip as ReactTooltip } from 'react-tooltip';
import 'react-tooltip/dist/react-tooltip.css';
import { TooltipContext } from './TooltipContext';

const Tooltip = ({ children, placement }) => {
  const { tooltip, closeTooltip } = React.useContext(TooltipContext);

  const handleMouseEnter = () => {
    if (!tooltip) {
      setTooltip({ children, placement });
    }
  };

  const handleMouseLeave = () => {
    closeTooltip();
  };

  return (
    <>
      {React.cloneElement(children, {
        onMouseEnter: handleMouseEnter,
        onMouseLeave: handleMouseLeave,
      })}
      {tooltip && (
        <ReactTooltip effect="solid" place={tooltip.placement}>
          {tooltip.children}
        </ReactTooltip>
      )}
    </>
  );
};

export default Tooltip;
```

