                    response = Encoding.ASCII.GetString(receiveBuffer, 0, bytes);
                    Console.WriteLine("Received temperature: " + response);

                    // Send the LOGOUT message
                    sendBuffer = Encoding.ASCII.GetBytes("LOGOUT");
                    stream.Write(sendBuffer, 0, sendBuffer.Length);
                    Console.WriteLine("Sent LOGOUT message.");
                }

                // Close everything
                client.Close();
            }
            catch (ArgumentNullException e)
            {
                Console.WriteLine("ArgumentNullException: {0}", e);
            }
            catch (SocketException e)
            {
                Console.WriteLine("SocketException: {0}", e);
            }

            Console.WriteLine("Press Enter to continue...");
