Here's a JavaScript implementation for packing and unpacking an array of entities into an ArrayBuffer. The entities have the fields `id` (4 bits) and `size` (3 bits).

```javascript
function packEntities(entities) {
  const buffer = new ArrayBuffer(entities.length);
  const view = new DataView(buffer);

  for (let i = 0; i < entities.length; i++) {
    const entity = entities[i];
    const id = entity.id & 0xF; // Masking to get the lower 4 bits
    const size = entity.size & 0x7; // Masking to get the lower 3 bits

    view.setUint8(i * (id + size), id);
    view.setUint8(i * (id + size) + 1, size);

    // Set the remaining bits of the byte with the entity data
    const offset = i * (id + size) + 2;
    const dataLength = view.byteLength - offset;
    const data = new Uint8Array(entities[i].data);
    for (let j = 0; j < Math.min(data.length, dataLength); j++) {
      view.setUint8(offset + j, data[j]);
    }
  }

  return buffer;
}

function unpackEntities(buffer, count) {
  const view = new DataView(buffer);
  const entities = [];

  for (let i = 0; i < count; i++) {
    const id = view.getUint8(i * 2);
    const size = view.getUint8(i * 2 + 1);

    // Calculate the data length based on the size and current position
    const dataLength = view.byteLength - (i * 2 + 2) - (id + size);
    const data = new Uint8Array(dataLength);

    for (let j = 0; j < dataLength; j++) {
      data[j] = view.getUint8(i * 2 + 2 + j);
    }

    entities.push({
      id: id << 4,
      size: size << 3,
      data: data
    });
  }

  return entities;
}
```

You can use these functions like this:

