  { id: 1, size: 1, data: new Uint8Array([4]) },
  { id: 2, size: 3, data: new Uint8Array([5, 6, 7]) }
];

const buffer = packEntities(entities);
console.log(buffer); // ArrayBuffer

const unpackedEntities = unpackEntities(buffer, entities.length);
console.log(unpackedEntities); // [ { id: 3, size: 2, data: Uint8Array(3) }, { id: 1, size: 1, data: Uint8Array(1) }, { id: 2, size: 3, data: Uint8Array(3) } ]
