2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.js
```

3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { get } from '@ember/object';
import { inject as service } from '@ember/service';
import { task, timeout } from 'ember-concurrency';
import { read } from 'ember-cli-json-api';
import CSVBuilder from 'csv-builder';
import { worker } from 'ember-cli-web-worker';

export default Service.extend({
  store: service(),

  downloadCSV: task(function* (modelName, queryParams) {
    const query = this.store.query(modelName, queryParams);

    // Fetch the data from the server
    const records = yield* read(query);

    // Build the CSV data
    const csvData = new CSVBuilder({
      separator: ',',
      newline: '\n',
      columns: records[0].attributes,
    })
      .build(records.map((record) => Object.values(record.attributes)));

    // Save the CSV data as a Blob
    const csvBlob = new Blob([csvData], { type: 'text/csv' });

    // Create a temporary link element to download the CSV file
    const link = document.createElement('a');
    link.href = URL.createObjectURL(csvBlob);
    link.download = `${modelName}.csv`;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }),

  // Web worker function to generate the CSV data asynchronously
  @worker
  async generateCSVData(records) {
    const csvData = new CSVBuilder({
      separator: ',',
      newline: '\n',
      columns: records[0].attributes,
    })
      .build(records.map((record) => Object.values(record.attributes)));

    return csvData;
  },
});
